from itertools import permutations
from collections import Counter
# create mapped-inner masks for demo2
D={k:{(r-1,c-1) for r,c in map(tuple,np.argwhere(p!=int(k))) if 1<=r<=5 and 1<=c<=5} for k,p in can.items()}
# convert input source holes (which source 5x5)
H={k:{(int(r),int(c)) for r,c in map(tuple,np.argwhere(p==1))} for k,p in mot.items()}
print('D',D)
print('H',H)
assign={'4':'2','9':'8','2':'0','3':'7','5':'6','7':'3'}

def eval_assign(f):
    canv=list(D); sources=list(H)
    best=99999; bests=[]
    for perm in permutations(sources):
        cost=sum(f(D[c],H[s]) for c,s in zip(canv,perm))
        if cost<best: best=cost;bests=[dict(zip(canv,perm))]
        elif cost==best:bests.append(dict(zip(canv,perm)))
    actual=sum(f(D[c],H[s]) for c,s in assign.items())
    print(f.__name__, 'actual',actual,'best',best,'num',len(bests), 'actual_best', assign in bests)
    print('first',bests[:4])

def symdiff(a,b): return len(a^b)
def over(a,b): return len(a&b)
def subset_penalty(a,b): return len(a-b)
def missing(a,b): return len(b-a)
def dice_dist(a,b): return 1-2*len(a&b)/(len(a)+len(b) or 1)
def jaccard_dist(a,b): return 1-len(a&b)/(len(a|b) or 1)
eval_assign(symdiff); eval_assign(subset_penalty); eval_assign(missing);eval_assign(dice_dist);eval_assign(jaccard_dist)

def neg_overlap(a,b): return -len(a&b)
def over_fraction(a,b): return -len(a&b)/(len(a) or 1)
def ratio_small(a,b): return -len(a&b)/(len(b) or 1)
eval_assign(neg_overlap); eval_assign(over_fraction);eval_assign(ratio_small)

