def cosine_dist(a,b): return 1-len(a&b)/((len(a)*len(b))**.5 or 1)
def corr_dist(a,b):
    # binary vector correlation over 25 positions
    n=25; pa=len(a)/n;pb=len(b)/n
    cov=len(a&b)/n-pa*pb
    sd=((pa*(1-pa)*pb*(1-pb))**.5)
    return 1-(cov/sd if sd else 0)

eval_assign(cosine_dist); eval_assign(corr_dist)

